const std = @import("std"); const norm = @import("pa-carz-norm.zig"); const labl = @import("pa-carz-labl.zig"); const civi = @import("ut-date-civi.zig"); const typz = @import("pa-carz-type.zig");
const Carz = typz.Carz;
const TWOW = [_][]const u8{ "land cruiser", "santa fe", "grand i10", "grand vitara", "grand livina", "mu-x" };
pub fn hostOfzz(urlz: []const u8) []const u8 { const star = if (std.mem.indexOf(u8, urlz, "://")) |posi| posi + 3 else 0; const rest = urlz[star..]; const endz = std.mem.indexOfAny(u8, rest, "/?#") orelse rest.len; const host = rest[0..endz]; return if (std.mem.startsWith(u8, host, "www.")) host[4..] else host; }
pub fn lidzOfzz(urlz: []const u8) []const u8 { const star = if (std.mem.indexOf(u8, urlz, "://")) |posi| posi + 3 else 0; var path = urlz[star..]; path = path[0 .. std.mem.indexOfAny(u8, path, "?#") orelse path.len]; while (path.len > 0 and path[path.len - 1] == '/') path = path[0 .. path.len - 1]; const slaz = std.mem.lastIndexOfScalar(u8, path, '/') orelse return ""; var segm = path[slaz + 1 ..]; if (std.mem.endsWith(u8, segm, ".htm")) segm = segm[0 .. segm.len - 4]; if (std.mem.endsWith(u8, segm, ".html")) segm = segm[0 .. segm.len - 5]; const dash = std.mem.lastIndexOfScalar(u8, segm, '-') orelse return segm; return segm[dash + 1 ..]; }
pub fn setzStrz(dstz: *[]const u8, valu: []const u8) void { if (dstz.*.len == 0 and valu.len > 0) dstz.* = valu; }
pub fn smalNumz(valu: []const u8) i64 { var posi: usize = 0; while (posi < valu.len and !std.ascii.isDigit(valu[posi])) posi += 1; var outp: i64 = 0; while (posi < valu.len and std.ascii.isDigit(valu[posi]) and outp < 100000) : (posi += 1) outp = outp * 10 + (valu[posi] - '0'); return outp; }
pub fn dateMill(valu: []const u8) i64 { var part: [3]i64 = .{ 0, 0, 0 }; var indx: usize = 0; var curr: i64 = 0; var any = false; for (valu) |byte| { if (std.ascii.isDigit(byte)) { curr = curr * 10 + (byte - '0'); any = true; } else if ((byte == '/' or byte == '-') and any and indx < 2) { part[indx] = curr; indx += 1; curr = 0; any = false; } else if (any) break; } if (!any or indx != 2) return 0; part[2] = curr; if (part[0] < 1 or part[0] > 31 or part[1] < 1 or part[1] > 12 or part[2] < 2000 or part[2] > 2100) return 0; return civi.civiDays(part[2], part[1], part[0]) * 86400000; }
pub fn pricOnly(line: []const u8) bool { const cutz = std.mem.indexOfScalar(u8, line, '(') orelse line.len; const core = line[0..cutz]; if (core.len > 40) return false; var digi = false; var posi: usize = 0; while (posi < core.len) { const byte = core[posi]; if (std.ascii.isDigit(byte)) { digi = true; posi += 1; continue; } if (byte == ' ' or byte == '.' or byte == ',' or byte == '-') { posi += 1; continue; } const rest = core[posi..]; var skip: usize = 0; for ([_][]const u8{ "triệu", "trieu", "tỷ", "tỉ", "vnđ", "vnd", "ty", "tr", "đ", "₫" }) |unit| { if (skip == 0 and rest.len >= unit.len and std.ascii.eqlIgnoreCase(rest[0..unit.len], unit)) skip = unit.len; } if (skip == 0) return false; posi += skip; } return digi; }
pub fn jsonRawz(blob: []const u8, keyz: []const u8, buff: []u8) []const u8 { var patz: [48]u8 = undefined; const patn = std.fmt.bufPrint(&patz, "\"{s}\":", .{keyz}) catch return ""; const posi = std.mem.indexOf(u8, blob, patn) orelse return ""; var rest = std.mem.trimStart(u8, blob[posi + patn.len ..], " "); if (rest.len > 0 and rest[0] == '"') rest = rest[1..]; var lenz: usize = 0; while (lenz < rest.len and lenz < buff.len and rest[lenz] != '"' and rest[lenz] != ',' and rest[lenz] != '}') : (lenz += 1) buff[lenz] = rest[lenz]; return buff[0..lenz]; }
pub fn makeFind(titl: []const u8) ?struct { make: []const u8, endz: usize } { var best: ?usize = null; var blen: usize = 0; var bnam: []const u8 = ""; for (labl.MAKE) |makz| { var posi: usize = 0; while (posi + makz.len <= titl.len) : (posi += 1) { if (!std.ascii.eqlIgnoreCase(titl[posi .. posi + makz.len], makz)) continue; const befo = posi == 0 or !std.ascii.isAlphanumeric(titl[posi - 1]); const afte = posi + makz.len == titl.len or !std.ascii.isAlphanumeric(titl[posi + makz.len]); if (!(befo and afte)) continue; if (best == null or posi < best.? or (posi == best.? and makz.len > blen)) { best = posi; blen = makz.len; bnam = makz; } break; } } if (best) |posi| return .{ .make = bnam, .endz = posi + blen }; return null; }
pub fn titlModl(carz: *Carz, titl: []const u8) void { const hitz = makeFind(titl) orelse return; if (carz.make.len == 0) carz.make = hitz.make; var rest = std.mem.trim(u8, titl[hitz.endz..], " -"); if (rest.len == 0) return; var toks = std.mem.tokenizeScalar(u8, rest, ' '); const tok0 = toks.next() orelse return; var modlEndz: usize = tok0.len; for (TWOW) |twoz| { if (rest.len >= twoz.len and std.ascii.eqlIgnoreCase(rest[0..twoz.len], twoz)) modlEndz = twoz.len; } if (carz.modl.len == 0) carz.modl = rest[0..modlEndz]; rest = std.mem.trim(u8, rest[modlEndz..], " "); const stop = std.mem.indexOfAny(u8, rest, ":-") orelse std.mem.indexOf(u8, rest, " giá ") orelse rest.len; var cutz = stop; var tok2 = std.mem.tokenizeScalar(u8, rest[0..stop], ' '); while (tok2.next()) |tokz| { if (norm.normYear(tokz) != 0 and tokz.len == 4) { cutz = @min(cutz, @intFromPtr(tokz.ptr) - @intFromPtr(rest.ptr)); break; } } if (carz.trim.len == 0) carz.trim = std.mem.trim(u8, rest[0..cutz], " -"); }
pub fn slugBonb(aren: std.mem.Allocator, carz: *Carz) !void { const star = (std.mem.indexOf(u8, carz.urlz, "/xe-") orelse return) + 4; var path = carz.urlz[star..]; path = path[0 .. std.mem.indexOfAny(u8, path, "?#/") orelse path.len]; var piec: std.ArrayList([]const u8) = .empty; var iter = std.mem.splitScalar(u8, path, '-'); while (iter.next()) |part| try piec.append(aren, part); if (piec.items.len < 4) return; const unde = struct { fn fixz(aloz: std.mem.Allocator, srcz: []const u8) ![]const u8 { const dupz = try aloz.dupe(u8, srcz); for (dupz) |*chrz| { if (chrz.* == '_') chrz.* = ' '; } return dupz; } }; carz.make = try unde.fixz(aren, piec.items[0]); carz.modl = try unde.fixz(aren, piec.items[1]); if (carz.year == 0) carz.year = norm.normYear(piec.items[piec.items.len - 2]); if (piec.items.len > 4) carz.trim = try std.mem.join(aren, " ", piec.items[2 .. piec.items.len - 2]); }
pub fn xtraAddz(aren: std.mem.Allocator, xtrz: *std.ArrayList(u8), cont: *u32, keyz: []const u8, valu: []const u8) !void { if (cont.* >= 24 or keyz.len > 40 or valu.len > 120) return; try xtrz.append(aren, if (cont.* == 0) '{' else ','); for ([_][]const u8{ keyz, valu }, 0..) |part, indx| { try xtrz.append(aren, '"'); for (part) |byte| { if (byte == '"' or byte == '\\') { try xtrz.append(aren, '\\'); try xtrz.append(aren, byte); } else if (byte >= 0x20) try xtrz.append(aren, byte); } try xtrz.append(aren, '"'); if (indx == 0) try xtrz.append(aren, ':'); } cont.* += 1; }
pub fn phonScan(aren: std.mem.Allocator, body: []const u8) ![]const u8 { var posi: usize = 0; while (posi < body.len) : (posi += 1) { if (body[posi] != '0' or (posi > 0 and std.ascii.isDigit(body[posi - 1]))) continue; var digs: [12]u8 = undefined; var cntz: usize = 0; var idx2 = posi; while (idx2 < body.len and cntz < 11) : (idx2 += 1) { const byte = body[idx2]; if (std.ascii.isDigit(byte)) { digs[cntz] = byte; cntz += 1; } else if (byte != '.' and byte != ' ' and byte != '-') break; } if (cntz == 10 and (digs[1] == '3' or digs[1] == '5' or digs[1] == '7' or digs[1] == '8' or digs[1] == '9') and !(idx2 < body.len and std.ascii.isDigit(body[idx2]))) return aren.dupe(u8, digs[0..cntz]); } return ""; }
pub fn titlPric(titl: []const u8) i64 { var segm: []const u8 = ""; if (std.mem.indexOf(u8, titl, " giá ")) |gpos| segm = titl[gpos + 5 ..] else if (std.mem.lastIndexOf(u8, titl, " - ")) |dpos| segm = titl[dpos + 3 ..]; if (std.mem.indexOf(u8, segm, " - ")) |cutz| segm = segm[0..cutz]; if (!(norm.hasz(segm, "tỷ") or norm.hasz(segm, "tỉ") or norm.hasz(segm, "triệu") or norm.hasz(segm, "tr"))) return 0; return norm.normPric(segm); }
pub fn kmzzScan(body: []const u8) i64 { var posi: usize = 0; while (posi + 2 <= body.len) : (posi += 1) { if (!std.ascii.eqlIgnoreCase(body[posi .. posi + 2], "km")) continue; if (posi + 2 < body.len and std.ascii.isAlphabetic(body[posi + 2])) continue; var endz = posi; while (endz > 0 and body[endz - 1] == ' ') endz -= 1; var star = endz; while (star > 0 and (std.ascii.isDigit(body[star - 1]) or body[star - 1] == '.' or body[star - 1] == ',')) star -= 1; if (star == endz) continue; const valu = norm.normKmzz(body[star..endz]); if (valu >= 0) return valu; } return -1; }
pub fn clasOfzz(carz: *const Carz) []const u8 { const pool = [_][]const u8{ carz.titl, carz.body }; for (pool) |tex0| { if (norm.hasz(tex0, "bán tải") or norm.hasz(tex0, "pickup")) return "pickup"; } for (pool) |tex0| { if (norm.hasz(tex0, "xe tải") or norm.hasz(tex0, "xe ben") or norm.hasz(tex0, "đầu kéo") or norm.hasz(tex0, "sơ mi") or norm.hasz(tex0, "rơ moóc") or norm.hasz(tex0, "đông lạnh") or norm.hasz(tex0, "tải ")) return "truck"; } for (pool) |tex0| { if (norm.hasz(tex0, "xe khách") or norm.hasz(tex0, "limousine") or norm.hasz(tex0, "xe bus")) return "bus"; } for (pool) |tex0| { if (norm.hasz(tex0, "minivan") or norm.hasz(tex0, "xe van") or norm.hasz(tex0, "van ")) return "van"; } return "car"; }
pub fn cleaTitl(titl: []const u8) []const u8 { var outp = titl; if (std.mem.indexOf(u8, outp, " | ")) |cutz| outp = outp[0..cutz]; for ([_][]const u8{ "Bán xe ô tô ", "Bán xe ", "Mua bán xe ", "Bán ô tô " }) |pref| { if (std.mem.startsWith(u8, outp, pref)) outp = outp[pref.len..]; } return std.mem.trim(u8, outp, " "); }
pub fn maskPhon(aren: std.mem.Allocator, body: []const u8) ![]const u8 { var outp: std.ArrayList(u8) = .empty; var posi: usize = 0; while (posi < body.len) { if (body[posi] == '0' and (posi == 0 or !std.ascii.isDigit(body[posi - 1]))) { var jdxz = posi; var digs: usize = 0; var last = posi; while (jdxz < body.len) { const bytz = body[jdxz]; if (std.ascii.isDigit(bytz)) { digs += 1; last = jdxz; jdxz += 1; } else if ((bytz == '.' or bytz == ' ' or bytz == '-') and jdxz + 1 < body.len and std.ascii.isDigit(body[jdxz + 1]) and digs < 14) jdxz += 1 else break; } if (digs >= 9 and digs <= 11) { try outp.appendSlice(aren, "[tel]"); posi = last + 1; continue; } } try outp.append(aren, body[posi]); posi += 1; } return outp.toOwnedSlice(aren); }
pub fn detaUrlz(urlz: []const u8) bool { const host = hostOfzz(urlz); const star = (std.mem.indexOf(u8, urlz, "://") orelse return false) + 3; const rest = urlz[star..]; const slaz = std.mem.indexOfScalar(u8, rest, '/') orelse return false; var path = rest[slaz..]; path = path[0 .. std.mem.indexOfAny(u8, path, "?#") orelse path.len]; if (std.mem.eql(u8, host, "bonbanh.com")) return std.mem.startsWith(u8, path, "/xe-"); if (std.mem.eql(u8, host, "carmudi.vn")) return std.mem.startsWith(u8, path, "/ban-xe-") and lidzDigi(path); if (std.mem.eql(u8, host, "carpla.vn")) return std.mem.startsWith(u8, path, "/xe/") and path.len > 4; if (std.mem.eql(u8, host, "oto.com.vn")) return std.mem.indexOf(u8, path, "aid") != null and std.mem.count(u8, path, "/") >= 2; if (std.mem.eql(u8, host, "tinbanxe.vn")) return std.mem.indexOf(u8, path, "-trang-") != null; if (std.mem.eql(u8, host, "xe.chotot.com")) return std.mem.endsWith(u8, path, ".htm"); return false; }
fn lidzDigi(path: []const u8) bool { const par2 = std.mem.trimEnd(u8, path, "/"); const dash = std.mem.lastIndexOfScalar(u8, par2, '-') orelse return false; const tail = par2[dash + 1 ..]; if (tail.len < 4) return false; for (tail) |bytz| { if (!std.ascii.isDigit(bytz)) return false; } return true; }// =======================___THIS_IS_THE_END___=======================
